define(["core/str"],function(e){return{init:function(e){var t=document.getElementById(e);if(t){if(document.getElementById(e+"_picker"))return;var n=document.createElement("input");n.type="color",n.id=e+"_picker",n.value=t.value||"#496637",n.style.marginLeft="10px",n.style.verticalAlign="middle",n.style.cursor="pointer",n.style.height="35px",n.style.width="40px",n.style.padding="0",n.style.border="1px solid #ccc",n.style.borderRadius="4px",t.parentNode.insertBefore(n,t.nextSibling),n.addEventListener("input",function(){t.value=n.value}),t.addEventListener("input",function(){/^#[0-9A-Fa-f]{6}$/i.test(t.value)&&(n.value=t.value)})}}}});